python -c "
import numpy as np
from scipy.spatial.distance import cdist
L=[l for l in open('init.xyz').read().split('\n')[2:] if l.strip()]
S=[l.split()[0] for l in L]; P=np.array([[float(x) for x in l.split()[1:]] for l in L])
D=cdist(P,P); np.fill_diagonal(D,9)
# fragment ids by connectivity
import networkx as nx
G=nx.Graph(); G.add_nodes_from(range(len(S)))
for i in range(len(S)):
    for j in range(i+1,len(S)):
        if D[i,j]<1.75: G.add_edge(i,j)
comp={n:k for k,c in enumerate(nx.connected_components(G)) for n in c}
pairs=[(D[i,j],i,S[i],j,S[j]) for i in range(len(S)) for j in range(i+1,len(S)) if comp[i]!=comp[j] and D[i,j]<2.2]
for p in sorted(pairs)[:15]: print(p)
"
